    bool merchantReady;
    void BuildMerchantTools()
    {
        void Page(string name,DataGridView grid,string explanation,params (string label,Action action)[] actions){var p=pages[name];var bar=Toolbar();foreach(var a in actions)bar.Controls.Add(Button(a.label,a.action));var note=Info(70);note.Text=explanation;p.Controls.Add(grid);p.Controls.Add(note);p.Controls.Add(bar);}
        Page("Merchant Goals",goalGrid,"Goals use this character's recorded mesos balance. Update the balance in Characters as you trade. Each goal is an independent target, not a reserved fund.",("Add goal",()=>EditMerchant("goal")),("Edit selected",()=>EditMerchant("goal",SelectedMerchant(goalGrid))),("Remove",()=>RemoveMerchant(SelectedMerchant(goalGrid))),("Update mesos",()=>EditCharacter(store.Characters().Single(c=>c.Id==store.Profile))));
        Page("Restock",restockGrid,"Choose a minimum stock level. Low stock is recorded in your Alert Inbox once per shortage; replenishing stock rearms the reminder. Only the active character is checked.",("Add reminder",()=>EditMerchant("restock")),("Edit selected",()=>EditMerchant("restock",SelectedMerchant(restockGrid))),("Remove",()=>RemoveMerchant(SelectedMerchant(restockGrid))),("Open bag",()=>ShowPage("Inventory")));
        Page("Gear Wishlist",wishGrid,"Save an exact equipment variant from a retrieved listing, or paste its complete variant text. Only recent available asks with complete matching stats qualify. A blank budget means any price.",("Add wish",()=>EditMerchant("wish")),("Edit selected",()=>EditMerchant("wish",SelectedMerchant(wishGrid))),("Remove",()=>RemoveMerchant(SelectedMerchant(wishGrid))),("Browse listings",()=>ShowPage("Price Checker")));
        var matches=new Panel(){Dock=DockStyle.Bottom,Height=200};var matchBar=Toolbar();matchBar.Controls.Add(Button("Open matching listing",()=>{if(SelectedMerchant(wishMatches) is Observation o)Open(o.Url);}));matches.Controls.Add(wishMatches);matches.Controls.Add(matchBar);pages["Gear Wishlist"].Controls.Add(matches);wishGrid.SelectionChanged+=(_,_)=>RenderWishMatches();
        Page("Item Notes",memoGrid,"Personal notes and tags stay with this character. Use Keep, Sell, Upgrade or For another character to organize your plans.",("Add note",()=>EditMerchant("memo")),("Edit selected",()=>EditMerchant("memo",SelectedMerchant(memoGrid))),("Remove",()=>RemoveMerchant(SelectedMerchant(memoGrid))));var memoBar=Toolbar();memoBar.Controls.Add(memoSearch);memoSearch.TextChanged+=(_,_)=>RenderMemos();pages["Item Notes"].Controls.Add(memoBar);
