        var p=pages["Price History"];var bar=Toolbar();bar.Controls.Add(chartItem);chartPeriod.Items.AddRange(["24 hours","7 days","14 days","30 days"]);chartPeriod.SelectedIndex=1;bar.Controls.Add(chartPeriod);bar.Controls.Add(Button("Reload history",ReloadChartChoices));chartItem.SelectedIndexChanged+=(_,_)=>RenderMerchantChart();chartPeriod.SelectedIndexChanged+=(_,_)=>RenderMerchantChart();p.Controls.Add(merchantChart);p.Controls.Add(chartSummary);p.Controls.Add(bar);
        var settingsBar=Toolbar();settingsBar.Height=58;settingsBar.Controls.Add(new Label(){Text="Town theme",AutoSize=true,Padding=new Padding(5,12,8,0)});themeChoice.Items.AddRange(MerchantTools.Themes);themeChoice.SelectedItem=features.Theme;themeChoice.SelectedIndexChanged+=(_,_)=>{features.Theme=themeChoice.Text;SaveFeatures();ApplyTownTheme();};settingsBar.Controls.Add(themeChoice);settingsBar.Controls.Add(Button("Setup guide",()=>ShowPage("Getting Started")));pages["Settings"].Controls.Add(settingsBar);
        BuildSetupGuide();var dashBar=Toolbar();dashBar.Controls.Add(Button("My goals",()=>ShowPage("Merchant Goals")));dashBar.Controls.Add(Button("Restock",()=>ShowPage("Restock")));dashBar.Controls.Add(Button("Trading session",()=>ShowPage("Trading Sessions")));dashBar.Controls.Add(Button("Setup guide",()=>ShowPage("Getting Started")));var dashboardPanel=new Panel(){Dock=DockStyle.Bottom,Height=124};dashboardPanel.Controls.Add(merchantDashboard);dashboardPanel.Controls.Add(dashBar);pages["Dashboard"].Controls.Add(dashboardPanel);
        merchantReady=true;RenderMerchantTools();ApplyTownTheme();
