    static object? SelectedMerchant(DataGridView grid)=>grid.SelectedRows.Count>0?grid.SelectedRows[0].Tag:null;
    void EditMerchant(string kind,object? existing=null)
    {
        using var d=EntryDialog(kind switch{"goal"=>"Merchant goal","restock"=>"Restock reminder","wish"=>"Exact equipment wishlist",_=>"Item note"},out var fields);
        var name=new TextBox(){MaxLength=250,Text=existing switch{MerchantGoal x=>x.Name,RestockRule x=>x.Name,GearWish x=>x.Name,ItemMemo x=>x.Name,_=>search.Text}};
        Field(fields,kind=="goal"?"Goal name":"Exact item name",name);
        var value=Amount(existing switch{MerchantGoal x=>x.Target,RestockRule x=>x.Minimum,GearWish x=>x.Maximum,_=>kind=="wish"?0:1},kind=="wish"?0:1,kind=="restock"?1_000_000_000:1_000_000_000_000m);
        if(kind!="memo")Field(fields,kind switch{"goal"=>"Target mesos balance","restock"=>"Minimum quantity",_=>"Maximum unit price (0 = any price)"},value);
        var variant=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDown,Text=(existing as GearWish)?.Variant??""};
        void FillVariants(){variant.Items.Clear();variant.Items.AddRange(EligibleObservations().Where(o=>o.Equipment&&o.VariantComplete&&TextKey.Search(o.Name)==TextKey.Search(name.Text)).Select(o=>o.Variant).Distinct().Cast<object>().ToArray());}
        if(kind=="wish"){FillVariants();name.TextChanged+=(_,_)=>FillVariants();Field(fields,"Complete exact variant (choose from cached listings)",variant);}
        var tag=new ComboBox(){DropDownStyle=ComboBoxStyle.DropDownList};tag.Items.AddRange(MerchantTools.Tags);tag.SelectedItem=(existing as ItemMemo)?.Tag??"Keep";var notes=new TextBox(){Multiline=true,Height=120,MaxLength=4000,Text=(existing as ItemMemo)?.Notes??""};if(kind=="memo"){Field(fields,"Tag",tag);Field(fields,"Notes",notes);}
        fields.Controls.Add(Button("Save",()=>{try{
            var copy=CompanionFeatures.Read(JsonSerializer.Serialize(features,Json.Options));string id=existing switch{MerchantGoal x=>x.Id,RestockRule x=>x.Id,GearWish x=>x.Id,ItemMemo x=>x.Id,_=>Guid.NewGuid().ToString()};
            switch(kind){case "goal":copy.Goals.RemoveAll(x=>x.Id==id);copy.Goals.Add(new(id,store.Profile,name.Text.Trim(),value.Value));break;case "restock":copy.Restocks.RemoveAll(x=>x.Id==id);copy.Restocks.Add(new(id,store.Profile,name.Text.Trim(),(long)value.Value));copy.LowStock.Remove(id);break;case "wish":copy.Wishes.RemoveAll(x=>x.Id==id);copy.Wishes.Add(new(id,store.Profile,name.Text.Trim(),variant.Text.Trim(),value.Value));break;default:copy.Memos.RemoveAll(x=>x.Id==id);copy.Memos.Add(new(id,store.Profile,name.Text.Trim(),tag.Text,notes.Text));break;}
            copy.Validate();copy.Save(FeaturePath);features=copy;if(kind=="wish"){var old=store.Items().FirstOrDefault(i=>TextKey.Search(i.Name)==TextKey.Search(name.Text));store.SaveItem(old is null?new SavedItem(name.Text.Trim(),0,true,false):old with{Watch=true});}Render();d.Close();
        }catch(Exception e){MessageBox.Show(e.Message,"Please check the entry");}}));d.ShowDialog(this);
    }
    void RemoveMerchant(object? entry)
    {
        if(entry is null)return;if(MessageBox.Show("Remove this saved entry? Recorded trades and inventory will remain.","Remove entry",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;
        switch(entry){case MerchantGoal x:features.Goals.Remove(x);break;case RestockRule x:features.Restocks.Remove(x);features.LowStock.Remove(x.Id);break;case GearWish x:features.Wishes.Remove(x);break;case ItemMemo x:features.Memos.Remove(x);break;case MerchantSession x:features.Sessions.Remove(x);break;}SaveFeatures();RenderMerchantTools();
    }
    void RenderMerchantTools()
    {
        if(!merchantReady)return;var profile=store.Profile;var character=store.Characters().Single(c=>c.Id==profile);var items=store.Items();
        SetColumns(goalGrid,["Goal","Balance / target","Progress","Mesos remaining"]);foreach(var x in features.Goals.Where(x=>x.Profile==profile)){var n=goalGrid.Rows.Add(x.Name,$"{TextKey.Mesos(character.Mesos)} / {TextKey.Mesos(x.Target)}",$"{MerchantTools.Progress(character.Mesos,x.Target):N1}%",TextKey.Mesos(Math.Max(0,x.Target-character.Mesos)));goalGrid.Rows[n].Tag=x;}
        SetColumns(restockGrid,["Item","Minimum","Owned","Need","Status"]);foreach(var x in features.Restocks.Where(x=>x.Profile==profile)){long need=MerchantTools.Needed(x,items);var n=restockGrid.Rows.Add(x.Name,x.Minimum,items.Where(i=>TextKey.Search(i.Name)==TextKey.Search(x.Name)).Sum(i=>i.Quantity),need,need>0?"Restock needed":"Stock ready");restockGrid.Rows[n].Tag=x;}
        SetColumns(wishGrid,["Equipment","Exact variant","Maximum ask","Matches"]);foreach(var x in features.Wishes.Where(x=>x.Profile==profile)){int n=wishGrid.Rows.Add(x.Name,x.Variant,x.Maximum==0?"Any":TextKey.Mesos(x.Maximum),EligibleObservations().Count(o=>MerchantTools.Matches(x,o,DateTimeOffset.UtcNow,settings.FreshHours)));wishGrid.Rows[n].Tag=x;}wishGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;wishGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;RenderWishMatches();RenderMemos();
        SetColumns(sessionGrid,["Session","Started / ended","Purchases","Sales","Fees","Matched profit","Unmatched units"]);foreach(var x in features.Sessions.Where(x=>x.Profile==profile).OrderByDescending(x=>x.Start)){var t=MerchantTools.Totals(x,features.Trades,DateTimeOffset.UtcNow);int n=sessionGrid.Rows.Add(x.Name,$"{x.Start.LocalDateTime:g} / {(x.End is null?"Active":x.End.Value.LocalDateTime.ToString("g"))}",TextKey.Mesos(t.Purchases),TextKey.Mesos(t.Sales),TextKey.Mesos(t.Fees),TextKey.Mesos(t.Profit),t.Unmatched);sessionGrid.Rows[n].Tag=x;}sessionGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;sessionGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;
        var active=features.Sessions.FirstOrDefault(s=>s.Profile==profile&&s.End is null);sessionSummary.Text=active is null?"No session running. Start one before recording your next trades.":$"Active: {active.Name} • started {active.Start.LocalDateTime:g}\nRecord completed purchases and sales in Trade Journal; they appear here automatically.";
        var goal=features.Goals.FirstOrDefault(g=>g.Profile==profile);merchantDashboard.Text=(goal is null?"Set a merchant goal to track your next purchase.":$"{goal.Name}: {MerchantTools.Progress(character.Mesos,goal.Target):N0}% • {TextKey.Mesos(Math.Max(0,goal.Target-character.Mesos))} mesos to go")+$"\n{features.Restocks.Count(r=>r.Profile==profile&&MerchantTools.Needed(r,items)>0)} items need restocking • {features.Wishes.Count(w=>w.Profile==profile)} gear wishes • "+(active is null?"No trading session running":"Session: "+active.Name);
        ReloadChartChoices();
    }
    void RenderMemos(){SetColumns(memoGrid,["Item","Tag","Notes"]);foreach(var x in features.Memos.Where(x=>x.Profile==store.Profile&&TextKey.Search(x.Name+" "+x.Tag+" "+x.Notes).Contains(TextKey.Search(memoSearch.Text)))){int n=memoGrid.Rows.Add(x.Name,x.Tag,x.Notes);memoGrid.Rows[n].Tag=x;}memoGrid.Columns[2].FillWeight=220;memoGrid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;memoGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}
    void RenderWishMatches(){SetColumns(wishMatches,["Matching listing","Ask","Source / seller","Last checked"]);if(SelectedMerchant(wishGrid) is not GearWish wish)return;foreach(var o in EligibleObservations().Where(o=>MerchantTools.Matches(wish,o,DateTimeOffset.UtcNow,settings.FreshHours)).OrderBy(o=>o.UnitPrice)){int n=wishMatches.Rows.Add(o.Name,TextKey.Mesos(o.UnitPrice),o.Provider+" / "+o.Seller,o.RetrievedAt.LocalDateTime.ToString("g"));wishMatches.Rows[n].Tag=o;}}
    void StartMerchantSession(){if(features.Sessions.Any(s=>s.Profile==store.Profile&&s.End is null)){MessageBox.Show("End the current session first.");return;}using var d=EntryDialog("Start trading session",out var fields);var name=new TextBox(){Text="Merchant run "+DateTime.Now.ToString("MMM d HH:mm"),MaxLength=250};Field(fields,"Session name",name);fields.Controls.Add(Button("Start",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;features.Sessions.Add(new(Guid.NewGuid().ToString(),store.Profile,name.Text.Trim(),DateTimeOffset.UtcNow,null){StartMesos=store.Characters().Single(c=>c.Id==store.Profile).Mesos});SaveFeatures();RenderMerchantTools();d.Close();}));d.ShowDialog(this);}
    void EndMerchantSession(){var active=features.Sessions.FirstOrDefault(s=>s.Profile==store.Profile&&s.End is null);if(active is null)return;features.Sessions[features.Sessions.IndexOf(active)]=active with{End=DateTimeOffset.UtcNow,EndMesos=store.Characters().Single(c=>c.Id==store.Profile).Mesos};SaveFeatures();RenderMerchantTools();}
    void CheckMerchantAlerts()
    {
        if(!merchantReady||DateTimeOffset.UtcNow<settings.SnoozedUntil)return;var items=store.Items();bool changed=false;
        foreach(var rule in features.Restocks.Where(r=>r.Profile==store.Profile)){var needed=MerchantTools.Needed(rule,items);if(needed==0){changed|=features.LowStock.Remove(rule.Id);continue;}if(items.Any(i=>TextKey.Search(i.Name)==TextKey.Search(rule.Name)&&i.Muted)||features.LowStock.Contains(rule.Id))continue;AddInbox("restock:"+rule.Id+":"+Guid.NewGuid(),"Restock: "+rule.Name,$"Need {needed:N0} more to reach your minimum of {rule.Minimum:N0}.","",itemName:rule.Name);features.LowStock.Add(rule.Id);changed=true;}
        foreach(var wish in features.Wishes.Where(w=>w.Profile==store.Profile)){if(items.Any(i=>TextKey.Search(i.Name)==TextKey.Search(wish.Name)&&i.Muted))continue;foreach(var row in EligibleObservations().Where(o=>MerchantTools.Matches(wish,o,DateTimeOffset.UtcNow,settings.FreshHours))){var key="wish:"+wish.Id+":"+row.Key+":"+row.UnitPrice.ToString(System.Globalization.CultureInfo.InvariantCulture);if(features.TargetNotifications.Contains(key))continue;AddInbox(key,"Gear match: "+wish.Name,$"Exact variant found • ask {TextKey.Mesos(row.UnitPrice)} • {row.Provider}",row.Url,row);features.TargetNotifications.Add(key);changed=true;}}
        if(changed)SaveFeatures();
    }
    sealed record ChartChoice(string Name,string Variant){public override string ToString()=>Name+(Variant.Length==0?"":" • "+Variant);}
    List<Observation> chartRows=[];
    void ReloadChartChoices(){if(!merchantReady)return;var old=chartItem.SelectedItem as ChartChoice;chartRows=store.History().Where(o=>settings.Sources.Any(s=>s.Authorized&&s.Id==o.Provider)&&(!o.Equipment||o.VariantComplete)).ToList();chartItem.Items.Clear();chartItem.Items.AddRange(chartRows.Select(o=>new ChartChoice(o.Name,o.Variant)).Distinct().OrderBy(x=>x.Name).Cast<object>().ToArray());if(old is not null&&chartItem.Items.Contains(old))chartItem.SelectedItem=old;else if(chartItem.Items.Count>0)chartItem.SelectedIndex=0;RenderMerchantChart();}
    void RenderMerchantChart(){var now=DateTimeOffset.UtcNow;int days=chartPeriod.SelectedIndex switch{0=>1,2=>14,3=>30,_=>7};var chosen=chartItem.SelectedItem as ChartChoice;merchantChart.Points=chosen is null?[]:MerchantTools.History(chartRows.Where(o=>TextKey.Search(o.Name)==TextKey.Search(chosen.Name)&&o.Variant==chosen.Variant&&o.ObservedAt>=now.AddDays(-days)&&o.ObservedAt<=now&&o.Kind==EvidenceKind.Asking));var rows=merchantChart.Points;chartSummary.Text=rows.Count==0?"No recorded asking history for this item and period. Browse or watch an item to collect real source observations.":$"{chosen!.Name} • {days} day(s) • {rows.Count:N0} distinct asking observations • {rows.Select(o=>o.Seller).Distinct().Count():N0} seller names • last checked {rows.Max(o=>o.RetrievedAt).LocalDateTime:g}\nExact equipment variants are kept separate. Dots show observed asks, not completed sales or a predicted value.";merchantChart.Invalidate();}
    void ApplyTownTheme()
    {
        var palette=features.Theme switch{"Ellinia"=>(Color.FromArgb(83,125,88),Color.FromArgb(222,237,207)),"Kerning City"=>(Color.FromArgb(93,104,129),Color.FromArgb(225,228,237)),"Perion"=>(Color.FromArgb(155,105,70),Color.FromArgb(244,225,195)),_=>(Color.FromArgb(112,153,176),Color.FromArgb(255,249,229))};ClassicPalette.Town=palette.Item1;ClassicPalette.Paper=palette.Item2;
        void Paint(Control c){if(c is DataGridView g){g.DefaultCellStyle.BackColor=palette.Item2;g.AlternatingRowsDefaultCellStyle.BackColor=ControlPaint.Light(palette.Item2);g.ColumnHeadersDefaultCellStyle.BackColor=ControlPaint.Light(palette.Item1);}else if(c is Panel&&c.Dock==DockStyle.Left)c.BackColor=palette.Item1;else if(c is HistoryPlot)c.BackColor=palette.Item2;c.Invalidate();foreach(Control child in c.Controls)Paint(child);}foreach(Control child in Controls)Paint(child);
    }
    void BuildSetupGuide()
    {
        var flow=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(18)};
        foreach(var step in new[]{("1. Your character","Create a character or storage profile and record your current mesos.","Characters"),("2. Fill your bag","Add your items, or use Bulk Import for a spreadsheet. Quantities stay local.","Inventory"),("3. Follow the market","Search items and add them to your watchlist to prioritize source checks.","Price Checker"),("4. Choose your alerts","Set price targets, exact gear wishes, and minimum stock reminders.","Price Alerts"),("5. Make it yours","Choose a town theme, text size and notification preferences.","Settings")}){flow.Controls.Add(new Label(){Text=step.Item1,Font=new Font("Tahoma",12,FontStyle.Bold),AutoSize=true,Margin=new Padding(3,15,3,3)});flow.Controls.Add(new Label(){Text=step.Item2,AutoSize=true,MaximumSize=new Size(750,0)});flow.Controls.Add(Button("Open "+step.Item3,()=>ShowPage(step.Item3)));}
        flow.Controls.Add(Button("Finish setup",()=>{features.SetupComplete=true;SaveFeatures();ShowPage("Dashboard");}));flow.Controls.Add(new Label(){Text="Reopen this guide from the dashboard or Settings. Prices appear only when supported sources provide real data.",AutoSize=true,MaximumSize=new Size(750,0),Margin=new Padding(3,15,3,3)});pages["Getting Started"].Controls.Add(flow);
    }
    async Task SmokeMerchantTools()
    {
        var before=JsonSerializer.Deserialize<PersonalBackup>(JsonSerializer.Serialize(Snapshot(),Json.Options),Json.Options)!;
        features.Goals.Add(new(Guid.NewGuid().ToString(),store.Profile,"Test gear fund",1000000));features.Restocks.Add(new(Guid.NewGuid().ToString(),store.Profile,"Red Potion",50));features.Memos.Add(new(Guid.NewGuid().ToString(),store.Profile,"Red Potion","Keep","Test personal note"));features.Sessions.Add(new(Guid.NewGuid().ToString(),store.Profile,"Test merchant run",DateTimeOffset.UtcNow,null));features.Wishes.Add(new(Guid.NewGuid().ToString(),store.Profile,"Test equipment","watk=25; remaining=7",10000));SaveFeatures();CheckMerchantAlerts();int count=features.Inbox.Count;CheckMerchantAlerts();if(features.Inbox.Count!=count)throw new Exception("Restock duplicate");RenderMerchantTools();if(goalGrid.Rows.Count==0||restockGrid.Rows.Count==0||memoGrid.Rows.Count==0||sessionGrid.Rows.Count==0)throw new Exception("Merchant page empty");
        foreach(var page in new[]{"Merchant Goals","Restock","Gear Wishlist","Item Notes","Trading Sessions","Price History","Getting Started","Dashboard"}){ShowPage(page);if(page=="Gear Wishlist"&&wishGrid.Bottom>wishMatches.Parent!.Top)throw new Exception("Wishlist match panel overlaps saved wishes");CapturePreview(Path.Combine(dataDirectory,page.Replace(" ","-").ToLowerInvariant()+"-11.png"));}
        foreach(var theme in MerchantTools.Themes){features.Theme=theme;ApplyTownTheme();ShowPage("Merchant Goals");CapturePreview(Path.Combine(dataDirectory,"theme-"+theme.Replace(" ","-")+".png"));}EndMerchantSession();if(features.Sessions.Any(s=>s.Profile==store.Profile&&s.End is null))throw new Exception("Session did not end");RestorePersonal(before);ApplyTownTheme();await Task.CompletedTask;
    }
}
internal static class ClassicPalette{internal static Color Town=Color.FromArgb(112,153,176),Paper=Color.FromArgb(255,249,229);}
